import numpy as np
from scipy import stats
from sklearn.linear_model import LogisticRegression
from sklearn.feature_selection import mutual_info_classif
from collections import defaultdict

MAX_DRIVERS = 5

def design(feats):
    # Identify strong candidates based on t-statistics
    strong_candidates = []
    for i, fid in enumerate(feats.ids):
        if feats.types[i] != 'clinical':
            t_stat = feats.x[:, feats.column(fid)] @ feats.y
            if abs(t_stat) > 4.0:
                strong_candidates.append((fid, abs(t_stat)))

    # Sort by strength
    strong_candidates.sort(key=lambda x: x[1], reverse=True)

    # Check for near-duplicates and remove them
    unique_candidates = []
    seen = set()
    for fid, _ in strong_candidates:
        if fid not in seen:
            unique_candidates.append(fid)
            seen.add(fid)

    # If no strong candidates, return empty design
    if len(unique_candidates) < 2:
        return Design(drivers=(), columns=(), products=(), loadings={})

    # Try to find interaction terms among top candidates
    top_features = unique_candidates[:10]
    best_score = -np.inf
    best_design = None

    # Try all pairs of features
    for i, a in enumerate(top_features):
        for j, b in enumerate(top_features[i+1:], i+1):
            # Compute interaction term
            col_a = feats.column(a)
            col_b = feats.column(b)
            interaction = feats.x[:, col_a] * feats.x[:, col_b]

            # Fit logistic regression with interaction
            X = np.column_stack([feats.x[:, feats.column(f)] for f in top_features if f != a and f != b])
            X = np.column_stack([X, interaction]) if X.size > 0 else interaction.reshape(-1, 1)

            try:
                lr = LogisticRegression(penalty='l2', C=1.0, fit_intercept=True, max_iter=1000)
                lr.fit(X, feats.y)
                score = lr.score(X, feats.y)
                if score > best_score:
                    best_score = score
                    best_design = Design(
                        drivers=(a, b),
                        columns=tuple(top_features),
                        products=((a, b),),
                        loadings={a: 1.0, b: 1.0}
                    )
            except:
                continue

    # If we found a good interaction, return it
    if best_design and best_score > 0.5:
        return best_design

    # Otherwise, return the strongest single feature
    if len(unique_candidates) > 0:
        return Design(
            drivers=(unique_candidates[0],),
            columns=(unique_candidates[0],),
            products=(),
            loadings={unique_candidates[0]: 1.0}
        )

    return Design(drivers=(), columns=(), products=(), loadings={})

